  std::any parseMarket(std::any market) override {
    //
    //     {
    //         "symbol": "BODEN-USD-PERP",
    //         "base_currency": "BODEN",
    //         "quote_currency": "USD",
    //         "settlement_currency": "USDC",
    //         "order_size_increment": "1",
    //         "price_tick_size": "0.00001",
    //         "min_notional": "200",
    //         "open_at": 1717065600000,
    //         "expiry_at": 0,
    //         "asset_kind": "PERP",
    //         "position_limit": "2000000",
    //         "price_bands_width": "0.2",
    //         "max_open_orders": 50,
    //         "max_funding_rate": "0.05",
    //         "delta1_cross_margin_params": {
    //             "imf_base": "0.2",
    //             "imf_shift": "180000",
    //             "imf_factor": "0.00071",
    //             "mmf_factor": "0.5"
    //         },
    //         "price_feed_id": "9LScEHse1ioZt2rUuhwiN6bmYnqpMqvZkQJDNUpxVHN5",
    //         "oracle_ewma_factor": "0.14999987905913592",
    //         "max_order_size": "520000",
    //         "max_funding_rate_change": "0.0005",
    //         "max_tob_spread": "0.2"
    //     }
    //
    // {
    //     "symbol":"BTC-USD-96000-C",
    //     "base_currency":"BTC",
    //     "quote_currency":"USD",
    //     "settlement_currency":"USDC",
    //     "order_size_increment":"0.001",
    //     "price_tick_size":"0.01",
    //     "min_notional":"100",
    //     "open_at":"1736764200000",
    //     "expiry_at":"0",
    //     "asset_kind":"PERP_OPTION",
    //     "market_kind":"cross",
    //     "position_limit":"10",
    //     "price_bands_width":"0.05",
    //     "iv_bands_width":"0.05",
    //     "max_open_orders":"100",
    //     "max_funding_rate":"0.02",
    //     "option_cross_margin_params":{
    //        "imf":{
    //           "long_itm":"0.2",
    //           "short_itm":"0.15",
    //           "short_otm":"0.1",
    //           "short_put_cap":"0.5",
    //           "premium_multiplier":"1"
    //        },
    //        "mmf":{
    //           "long_itm":"0.1",
    //           "short_itm":"0.075",
    //           "short_otm":"0.05",
    //           "short_put_cap":"0.5",
    //           "premium_multiplier":"0.5"
    //        }
    //     },
    //     "price_feed_id":"GVXRSBjFk6e6J3NbVPXohDJetcTjaeeuykUpbQF8UoMU",
    //     "oracle_ewma_factor":"0.20000046249626113",
    //     "max_order_size":"2",
    //     "max_funding_rate_change":"0.02",
    //     "max_tob_spread":"0.2",
    //     "interest_rate":"0.0001",
    //     "clamp_rate":"0.02",
    //     "option_type":"CALL",
    //     "strike_price":"96000",
    //     "funding_period_hours":"24",
    //     "tags":[
    //     ]
    //  }
    //
    std::any assetKind = this->safeString(market, std::string("asset_kind"));
    std::any isOptionPerpetual =
        (isEqual(assetKind, std::string("PERP_OPTION")));
    std::any isOptionDelivery = (isEqual(assetKind, std::string("OPTION")));
    std::any isOption = isTrue(isOptionPerpetual) || isTrue(isOptionDelivery);
    std::any type = (isTrue((isOption)) ? std::any(std::string("option"))
                                        : std::any(std::string("swap")));
    std::any isSwap = (isEqual(type, std::string("swap")));
    std::any marketId = this->safeString(market, std::string("symbol"));
    std::any quoteId = this->safeString(market, std::string("quote_currency"));
    std::any baseId = this->safeString(market, std::string("base_currency"));
    std::any quote = this->safeCurrencyCode(quoteId);
    std::any base = this->safeCurrencyCode(baseId);
    std::any settleId =
        this->safeString(market, std::string("settlement_currency"));
    std::any settle = this->safeCurrencyCode(settleId);
    std::any symbol = add(
        add(add(add(base, std::string("/")), quote), std::string(":")), settle);
    std::any expiry = this->safeInteger(market, std::string("expiry_at"));
    std::any optionType = this->safeString(market, std::string("option_type"));
    std::any strikePrice =
        this->safeString(market, std::string("strike_price"));
    std::any takerFee = this->parseNumber(std::string("0.0003"));
    std::any makerFee = this->parseNumber(std::string("-0.00005"));
    if (isTrue(isOption)) {
      std::any optionTypeSuffix =
          (isTrue((isEqual(optionType, std::string("CALL"))))
               ? std::any(std::string("C"))
               : std::any(std::string("P")));
      std::any deliveryValue =
          (isTrue((isEqual(expiry, 0)))
               ? std::any(std::string(""))
               : std::any(add(this->yymmdd(expiry), std::string("-"))));
      symbol = add(add(add(add(add(symbol, std::string("-")), deliveryValue),
                           strikePrice),
                       std::string("-")),
                   optionTypeSuffix);
      makerFee = this->parseNumber(std::string("0.0003"));
    } else {
      expiry = std::any{};
    }
    std::any expireDatetime =
        (isTrue((isEqual(expiry, 0))) ? std::any(std::any{})
                                      : std::any(this->iso8601(expiry)));
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), marketId},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), settle},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), settleId},
        {std::string("type"), type},
        {std::string("spot"), false},
        {std::string("margin"), std::any{}},
        {std::string("swap"), isSwap},
        {std::string("future"), false},
        {std::string("option"), isOption},
        {std::string("active"),
         this->safeBool(market, std::string("enableTrading"))},
        {std::string("contract"), true},
        {std::string("linear"), true},
        {std::string("inverse"), false},
        {std::string("taker"), takerFee},
        {std::string("maker"), makerFee},
        {std::string("contractSize"), this->parseNumber(std::string("1"))},
        {std::string("expiry"), expiry},
        {std::string("expiryDatetime"), expireDatetime},
        {std::string("strike"), this->parseNumber(strikePrice)},
        {std::string("optionType"),
         this->safeStringLower(market, std::string("option_type"))},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->safeNumber(market, std::string("order_size_increment"))},
             {std::string("price"),
              this->safeNumber(market, std::string("price_tick_size"))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"), std::any{}},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"),
                   this->safeNumber(market, std::string("max_order_size"))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"), std::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("min_notional"))},
                  {std::string("max"), std::any{}},
              }},
         }},
        {std::string("created"), std::any{}},
        {std::string("info"), market},
    });
  }

  virtual std::any parseTradingFee(std::any fee, std::any market = std::any{}) {
    //
    //     {
    //         "symbol": "BTC-USD-PERP",
    //         "fee_config": {
    //             "api_fee": {
    //                 "maker_fee": {
    //                     "fee": "0.000075",
    //                     "fee_cap": "0.125",
    //                     "fee_floor": "-0.125"
    //                 },
    //                 "taker_fee": {
    //                     "fee": "0.000125",
    //                     "fee_cap": "0.125",
    //                     "fee_floor": "-0.125"
    //                 }
    //             }
    //         }
    //     }
    //
    std::any marketId = this->safeString(fee, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any feeConfig =
        this->safeDict(fee, std::string("fee_config"), ccxt::dict{});
    std::any apiFee =
        this->safeDict(feeConfig, std::string("api_fee"), ccxt::dict{});
    std::any makerFee =
        this->safeDict(apiFee, std::string("maker_fee"), ccxt::dict{});
    std::any takerFee =
        this->safeDict(apiFee, std::string("taker_fee"), ccxt::dict{});
    return ccxt::dict{
        {std::string("info"), fee},
        {std::string("symbol"), ::getValue(market, std::string("symbol"))},
        {std::string("maker"),
         this->safeNumber(makerFee, std::string("fee"),
                          this->safeNumber(market, std::string("maker")))},
        {std::string("taker"),
         this->safeNumber(takerFee, std::string("fee"),
                          this->safeNumber(market, std::string("taker")))},
        {std::string("percentage"), true},
        {std::string("tierBased"), false},
    };
  }

  /**
   * @method
   * @name paradex#fetchTradingFee
   * @description fetch the trading fees for a market
   * @see https://docs.paradex.trade/api/prod/markets/get-markets
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<std::any>
  fetchTradingFee(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchTradingFee() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = awaitValue(
                     this->publicGetMarkets(this->extend(request, params)));
                 //
                 //     {
                 //         "results": [
                 //             {
                 //                 "symbol": "BTC-USD-PERP",
                 //                 "fee_config": {
                 //                     "api_fee": {
                 //                         "maker_fee": {
                 //                             "fee": "0.000075"
                 //                         },
                 //                         "taker_fee": {
                 //                             "fee": "0.000125"
                 //                         }
                 //                     }
                 //                 }
                 //             }
                 //         ]
                 //     }
                 //
                 std::any data = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 std::any first = this->safeDict(data, 0, ccxt::dict{});
                 return this->parseTradingFee(first, market);
               })
        .share();
  }

  /**
   * @method
   * @name paradex#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://docs.paradex.trade/api/prod/markets/get-markets
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<std::any>
  fetchTradingFees(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any response = awaitValue(this->publicGetMarkets(params));
                 //
                 //     {
                 //         "results": [
                 //             {
                 //                 "symbol": "BTC-USD-PERP",
                 //                 "fee_config": {
                 //                     "api_fee": {
                 //                         "maker_fee": {
                 //                             "fee": "0.000075"
                 //                         },
                 //                         "taker_fee": {
                 //                             "fee": "0.000125"
                 //                         }
                 //                     }
                 //                 }
                 //             }
                 //         ]
                 //     }
                 //
                 std::any fees = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 std::any result = ccxt::dict{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(fees));
                      postFixIncrement(i)) {
                   std::any fee = this->parseTradingFee(::getValue(fees, i));
                   std::any symbol = ::getValue(fee, std::string("symbol"));
                   ::setValue(result, symbol, fee);
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name paradex#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://docs.paradex.trade/api/prod/markets/klines
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @param {string} [params.price] "last", "mark", "index", default is "last"
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("resolution"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any now = this->milliseconds();
                 std::any duration = this->parseTimeframe(timeframe);
                 std::any until = this->safeInteger2(
                     params, std::string("until"), std::string("till"), now);
                 std::any price =
                     this->safeString(params, std::string("price"));
                 if (isTrue(!isEqual(price, std::any{}))) {
                   ::setValue(request, std::string("price_kind"), price);
                 }
                 params = this->omit(params, ccxt::list{std::string("until"),
                                                        std::string("till"),
                                                        std::string("price")});
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("start_at"), since);
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(
                         request, std::string("end_at"),
                         subtract(this->sum(since,
                                            multiply(multiply(duration,
                                                              (add(limit, 1))),
                                                     1000)),
                                  1));
                   } else {
                     ::setValue(request, std::string("end_at"), until);
                   }
                 } else {
                   ::setValue(request, std::string("end_at"), until);
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(
                         request, std::string("start_at"),
                         add(subtract(until, multiply(multiply(duration,
                                                               (add(limit, 1))),
                                                      1000)),
                             1));
                   } else {
                     ::setValue(
                         request, std::string("start_at"),
                         add(subtract(until,
                                      multiply(multiply(duration, 101), 1000)),
                             1));
                   }
                 }
                 std::any response = awaitValue(this->publicGetMarketsKlines(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "results": [
                 //             [
                 //                 1720071900000,
                 //                 58961.3,
                 //                 58961.3,
                 //                 58961.3,
                 //                 58961.3,
                 //                 1591
                 //             ]
                 //         ]
                 //     }
                 //
                 std::any data = this->safeList(
                     response, std::string("results"), ccxt::list{});
                 return this->parseOHLCVs(data, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    //
    //     [
    //         1720071900000,
    //         58961.3,
    //         58961.3,
    //         58961.3,
    //         58961.3,
    //         1591
    //     ]
    //
    return ccxt::list{this->safeInteger(ohlcv, 0), this->safeNumber(ohlcv, 1),
                      this->safeNumber(ohlcv, 2),  this->safeNumber(ohlcv, 3),
                      this->safeNumber(ohlcv, 4),  this->safeNumber(ohlcv, 5)};
  }

